28:     );
29:   }, [cart]);
30: 
31:   const handleComprar = () => {
32:     if (isAuthenticated()) {
33:       navigate(routes.CARDS);
34:     } else {
35:       navigate(routes.LOGIN);
36:     }
37:   };
38: 
39:   const addProductToCart = (data) => {
40:     dispatch(addProductToCartAction(data));
41:   };
42: 
43:   return (
44:     <div className="container pb-5">
45:       <Anchor.GoBack path={routes.HOME} text="Voltar aos produtos" />
46: 
47:       <div className="d-flex justify-content-center">
48:         <Typography.Title>Meu Carrinho</Typography.Title>
49:       </div>
50: 
51:       {cart.produtos.length === 0 ? (
52:         <Info className="d-flex justify-content-center mt-5">
53:           Seu carrinho está vazio.
54:         </Info>
55:       ) : (
56:         <>
57:           <div className="d-flex flex-column align-items-center">
58:             {cart.produtos.map((produto) => (
59:               <CartProduct
60:                 key={produto.id}
61:                 produto={produto}
62:                 removeProductFromCartAction={removeProductFromCartAction}
63:               />
64:             ))}
65:           </div>
66: 
67:           <div className="d-flex justify-content-center mt-3 mb-3">
68:             <Total>Total: {currencyFormatter(total)}</Total>
69:           </div>
70: 
71:           <div className="card-body d-flex justify-content-center mb-5 mt=4">
72:             <Button.Danger
73:               width="40%"
74:               onClick={() => dispatch(cleanCartAction())}
75:             >
76:               Limpar Carrinho
77:             </Button.Danger>
78: 
79:             <Button.Secondary
80:               width="45%"
81:               margin="0 10px"
82:               onClick={handleComprar}
83:             >
84:               Continuar
85:             </Button.Secondary>
86:           </div>
87:         </>
88:       )}
89: 
90:       <BestOffersFragment addProductToCart={addProductToCart} cart={cart} />
91:     </div>
92:   );
93: };
94: 
95: export default Cart;

